WHERE id IN (
    'c2000000-0000-0000-0000-000000000001',
    'c2000000-0000-0000-0000-000000000002',
    'c2000000-0000-0000-0000-000000000003',
    'c2000000-0000-0000-0000-000000000004'
) AND gathering_type IS NULL;

