INSERT INTO reviews (id, created_at, updated_at, review_content, review_type, like_count, is_home_featured, home_display_order, application_id, gathering_id, user_id)
VALUES
    ('e0000001-0000-0000-0000-000000000001', NOW(), NOW(), '처음엔 어색할 줄 알았는데 금방 친해졌어요. 분위기가 너무 좋았고 다음에도 꼭 참여하고 싶어요!',            'PHOTO', 3, TRUE,  1, 'f0000001-0000-0000-0000-000000000001', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000002'),
    ('e0000001-0000-0000-0000-000000000002', NOW(), NOW(), '새로운 사람들과 편하게 이야기 나눌 수 있어서 좋았어요. 같은 고민을 가진 사람들을 만난 것 같아서 힐링됐어요.', 'PHOTO', 5, TRUE,  2, 'f0000001-0000-0000-0000-000000000002', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000003'),
    ('e0000001-0000-0000-0000-000000000003', NOW(), NOW(), '처음 만나는 사람들인데 금방 편해졌어요. 큐레이터분이 분위기를 잘 이끌어주셔서 자연스럽게 대화가 이어졌어요.', 'TEXT', 2, FALSE, 0, 'f0000001-0000-0000-0000-000000000003', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000004'),
    ('e0000001-0000-0000-0000-000000000004', NOW(), NOW(), '와썹하우스 덕분에 서울에서 새로운 친구를 사귈 수 있었어요. 혼자 신청했는데 전혀 어색하지 않았어요.',           'PHOTO', 4, TRUE,  3, 'f0000001-0000-0000-0000-000000000004', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000005'),
    ('e0000001-0000-0000-0000-000000000005', NOW(), NOW(), '음악이랑 분위기가 너무 좋았어요. 다음 게더링도 꼭 참여할게요!',                                           'PHOTO', 1, FALSE, 0, 'f0000001-0000-0000-0000-000000000005', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000006'),
    ('e0000001-0000-0000-0000-000000000006', NOW(), NOW(), '큐레이터분이 분위기를 너무 잘 이끌어주셔서 자연스럽게 대화가 이어졌어요. 강추합니다!',                        'TEXT',  6, TRUE,  4, 'f0000001-0000-0000-0000-000000000006', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000007'),
    ('e0000001-0000-0000-0000-000000000007', NOW(), NOW(), '퇴근하고 바로 갔는데 사진 찍기 좋은 분위기였어요. 어색함 없이 금방 친해져서 시간 가는 줄 몰랐네요.',          'PHOTO', 4, FALSE, 0, 'f0000001-0000-0000-0000-000000000012', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000007'),
    ('e0000001-0000-0000-0000-000000000008', NOW(), NOW(), '혼자 와도 전혀 부담 없었어요. 큐레이터분이 잘 챙겨주셔서 편하게 즐겼습니다.',                                'TEXT',  2, FALSE, 0, 'f0000001-0000-0000-0000-000000000013', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000010'),
    ('e0000001-0000-0000-0000-000000000009', NOW(), NOW(), '맥주 한 잔 하면서 솔직한 이야기 많이 나눴어요. 사진도 많이 남겨서 좋았습니다!',                              'PHOTO', 5, FALSE, 0, 'f0000001-0000-0000-0000-000000000011', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000009'),
    ('e0000001-0000-0000-0000-000000000010', NOW(), NOW(), '또래들이랑 편하게 이야기할 수 있어서 좋았어요. 분위기 사진도 잔뜩 찍었네요 :)',                              'PHOTO', 3, FALSE, 0, 'f0000001-0000-0000-0000-000000000014', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000002'),
    ('e0000001-0000-0000-0000-000000000011', NOW(), NOW(), '같은 관심사를 가진 사람들을 만나서 대화가 끊기지 않았어요. 다음에 또 올게요.',                              'TEXT',  1, FALSE, 0, 'f0000001-0000-0000-0000-000000000015', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000006'),
    ('e0000001-0000-0000-0000-000000000012', NOW(), NOW(), '공간이 너무 예뻐서 계속 사진 찍었어요. 사람들도 좋았고 만족스러운 모임이었습니다.',                          'PHOTO', 7, FALSE, 0, 'f0000001-0000-0000-0000-000000000016', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000008')
