INSERT INTO reviews (id, created_at, updated_at, review_content, review_type, like_count, is_home_featured, home_display_order, application_id, gathering_id, user_id)
VALUES
    ('e0000001-0000-0000-0000-000000000013', NOW(), NOW(), '혼자 왔는데 다들 친절해서 금방 적응했어요. 대화 주제도 자연스럽게 이어졌습니다.', 'TEXT', 66, FALSE, 0, 'f0000001-0000-0000-0000-000000000017', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000002'),
    ('e0000001-0000-0000-0000-000000000014', NOW(), NOW(), '처음 보는 사이인데도 어색하지 않게 잘 풀어주셔서 좋았어요.', 'TEXT', 26, FALSE, 0, 'f0000001-0000-0000-0000-000000000018', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000003'),
    ('e0000001-0000-0000-0000-000000000015', NOW(), NOW(), '퇴근하고 와서 피곤했는데 오히려 에너지를 받고 갔습니다.', 'TEXT', 70, FALSE, 0, 'f0000001-0000-0000-0000-000000000019', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000004'),
    ('e0000001-0000-0000-0000-000000000016', NOW(), NOW(), '소규모라 한 명 한 명이랑 깊게 이야기할 수 있어서 만족했어요.', 'TEXT', 21, FALSE, 0, 'f0000001-0000-0000-0000-000000000020', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000005'),
    ('e0000001-0000-0000-0000-000000000017', NOW(), NOW(), '기대 안 하고 왔는데 생각보다 훨씬 즐거웠어요. 다음에 또 신청할게요.', 'TEXT', 29, FALSE, 0, 'f0000001-0000-0000-0000-000000000021', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000006'),
    ('e0000001-0000-0000-0000-000000000018', NOW(), NOW(), '분위기가 편안해서 낯가리는 저도 편하게 참여했습니다.', 'TEXT', 81, FALSE, 0, 'f0000001-0000-0000-0000-000000000022', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000007'),
    ('e0000001-0000-0000-0000-000000000019', NOW(), NOW(), '또래 친구들을 만나서 요즘 고민도 나누고 위로받고 왔어요.', 'TEXT', 75, FALSE, 0, 'f0000001-0000-0000-0000-000000000023', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000008'),
    ('e0000001-0000-0000-0000-000000000020', NOW(), NOW(), '진행이 매끄러워서 시간 가는 줄 몰랐어요. 강력 추천합니다.', 'TEXT', 61, FALSE, 0, 'f0000001-0000-0000-0000-000000000024', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000009'),
    ('e0000001-0000-0000-0000-000000000021', NOW(), NOW(), '취향이 비슷한 사람들이 모여서 대화가 정말 잘 통했어요.', 'TEXT', 4, FALSE, 0, 'f0000001-0000-0000-0000-000000000025', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000010'),
    ('e0000001-0000-0000-0000-000000000022', NOW(), NOW(), '혼자 사는 사람들끼리 공감대가 커서 마음이 따뜻해졌습니다.', 'TEXT', 87, FALSE, 0, 'f0000001-0000-0000-0000-000000000026', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000011'),
    ('e0000001-0000-0000-0000-000000000023', NOW(), NOW(), '처음엔 긴장했는데 끝날 땐 다 같이 웃고 있었어요.', 'TEXT', 62, FALSE, 0, 'f0000001-0000-0000-0000-000000000027', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000002'),
    ('e0000001-0000-0000-0000-000000000024', NOW(), NOW(), '네트워킹 목적으로 갔는데 좋은 인연도 만들고 왔습니다.', 'TEXT', 6, FALSE, 0, 'f0000001-0000-0000-0000-000000000028', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000003'),
    ('e0000001-0000-0000-0000-000000000025', NOW(), NOW(), '장소도 깔끔하고 동선도 편했어요. 운영이 세심하다는 느낌.', 'TEXT', 58, FALSE, 0, 'f0000001-0000-0000-0000-000000000029', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000004'),
    ('e0000001-0000-0000-0000-000000000026', NOW(), NOW(), '가볍게 참여했는데 생각보다 알찬 시간이었어요.', 'TEXT', 7, FALSE, 0, 'f0000001-0000-0000-0000-000000000030', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000005'),
    ('e0000001-0000-0000-0000-000000000027', NOW(), NOW(), '다양한 직군의 사람들을 만나서 시야가 넓어진 기분이에요.', 'TEXT', 85, FALSE, 0, 'f0000001-0000-0000-0000-000000000031', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000006'),
    ('e0000001-0000-0000-0000-000000000028', NOW(), NOW(), '사진 찍기 좋은 공간이라 인생샷 많이 건졌어요!', 'PHOTO', 79, FALSE, 0, 'f0000001-0000-0000-0000-000000000032', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000007'),
    ('e0000001-0000-0000-0000-000000000029', NOW(), NOW(), '분위기 너무 예뻐서 사진으로 다 담아왔습니다.', 'PHOTO', 9, FALSE, 0, 'f0000001-0000-0000-0000-000000000033', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000008'),
    ('e0000001-0000-0000-0000-000000000030', NOW(), NOW(), '조명이랑 인테리어가 감성적이라 계속 셔터를 눌렀네요.', 'PHOTO', 76, FALSE, 0, 'f0000001-0000-0000-0000-000000000034', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000009'),
    ('e0000001-0000-0000-0000-000000000031', NOW(), NOW(), '다 같이 찍은 사진 보니 그날 기억이 새록새록 나요.', 'PHOTO', 60, FALSE, 0, 'f0000001-0000-0000-0000-000000000035', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000010'),
    ('e0000001-0000-0000-0000-000000000032', NOW(), NOW(), '음식이랑 음료도 예뻐서 사진부터 찍고 먹었어요.', 'PHOTO', 0, FALSE, 0, 'f0000001-0000-0000-0000-000000000036', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000011'),
    ('e0000001-0000-0000-0000-000000000033', NOW(), NOW(), '노을 질 때 풍경이 정말 멋졌어요. 사진 강추!', 'PHOTO', 1, FALSE, 0, 'f0000001-0000-0000-0000-000000000037', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000002'),
    ('e0000001-0000-0000-0000-000000000034', NOW(), NOW(), '사람들 표정이 다 밝아서 사진마다 분위기가 살아있어요.', 'PHOTO', 33, FALSE, 0, 'f0000001-0000-0000-0000-000000000038', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000003'),
    ('e0000001-0000-0000-0000-000000000035', NOW(), NOW(), '공간 구석구석이 포토존이라 셀카도 단체샷도 만족.', 'PHOTO', 67, FALSE, 0, 'f0000001-0000-0000-0000-000000000039', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000004'),
    ('e0000001-0000-0000-0000-000000000036', NOW(), NOW(), '현장 사진 첨부해요. 분위기 궁금한 분들 참고하세요!', 'PHOTO', 35, FALSE, 0, 'f0000001-0000-0000-0000-000000000040', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000005'),
    ('e0000001-0000-0000-0000-000000000037', NOW(), NOW(), '기록용으로 찍었는데 다시 봐도 좋네요. 또 가고 싶어요.', 'PHOTO', 51, FALSE, 0, 'f0000001-0000-0000-0000-000000000041', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000006'),
    ('e0000001-0000-0000-0000-000000000038', NOW(), NOW(), '햇살 좋은 날 야외라 사진이 다 화보처럼 나왔어요.', 'PHOTO', 77, FALSE, 0, 'f0000001-0000-0000-0000-000000000042', 'c2000000-0000-0000-0000-000000000002', 'b1000000-0000-0000-0000-000000000007'),
    ('e0000001-0000-0000-0000-000000000039', NOW(), NOW(), '직접 찍은 사진들 올려요. 와썹하우스 분위기 이런 느낌!', 'PHOTO', 93, FALSE, 0, 'f0000001-0000-0000-0000-000000000043', 'c2000000-0000-0000-0000-000000000001', 'b1000000-0000-0000-0000-000000000008')
